    has_iflist=False
    has_readscan=False
    seed_explicit=False

    def add_empty(opt):
        stderr_buf.append(f"{opt}: empty parameter")

    i=0
    while i < len(raw_argv):
        token=raw_argv[i]
        if re.fullmatch(r'-v+', token) or re.fullmatch(r'-d+', token):
            i+=1
            continue

        if token=='-c' or token=='--conf' or token=='--config' or (token.startswith('-c') and not token.startswith('--') and len(token)>2):
            path=None
            if token in ('-c','--conf','--config'):
                if i+1>=len(raw_argv):
                    add_empty('conf')
                    i+=1
                    continue
                path=raw_argv[i+1]
                i+=2
            else:
                path=token[2:]
                i+=1
                if not path:
                    add_empty('conf')
                    continue
            if not os.path.exists(path):
                stderr_buf.append("[-] FAIL: reading configuration file")
                stderr_buf.append(f"[-] {path}: No such file or directory")
                stderr_buf.append(f"[-] cwd = {os.getcwd()}")
                continue
            try:
                with open(path,'r') as f:
                    flines=f.readlines()
