                stderr_buf.append(f"[-] {path}: No such file or directory")
                stderr_buf.append(f"[-] cwd = {os.getcwd()}")
                continue
            for line in flines:
                line=line.strip()
                if not line or line.startswith('#'):
                    continue
                if '=' in line:
                    k,v=line.split('=',1)
