                    sys.exit(1)
                cfg['adapter_ip']=val
                continue
            elif token.startswith('-g'):
                if token=='-g':
                    if i+1>=len(raw_argv) or raw_argv[i+1].startswith('-'):
                        stderr_buf.append("g: empty parameter")
                        i+=1
                        continue
                    val=raw_argv[i+1]
                    i+=2
                else:
                    val=token[2:]
                    if not val:
                        stderr_buf.append("g: empty parameter")
                        i+=1
                        continue
                    i+=1
                try:
                    cfg['adapter_port']=int(val.split(',')[0].split('-')[0])
                except:
                    pass
                continue
            elif token.startswith('-iL'):
                if token=='-iL':
                    if i+1>=len(raw_argv) or raw_argv[i+1].startswith('-'):
                        stderr_buf.append("iL: empty parameter")
                        i+=1
                        continue
                    val=raw_argv[i+1]
                    i+=2
                else:
                    val=token[3:]
                    if not val:
                        stderr_buf.append("iL: empty parameter")
                        i+=1
                        continue
                    i+=1
                if not os.path.exists(val):
                    sys.stderr.write(f"[-] FAIL: parsing IP addresses\n[-] {val}: No such file or directory\n")
                    sys.exit(1)
                else:
                    rr,errmsg=read_ip_file(val)
                    if rr:
                        cfg['include_ranges'].extend(rr)
                continue
            elif token.startswith('-o'):
                if len(token)>=3:
                    fmt_char=token[2]
                    rest=token[3:]
                    if rest:
                        filename=rest
                        i+=1
                    else:
                        if i+1>=len(raw_argv):
                            stderr_buf.append(f"o{fmt_char}: empty parameter")
                            i+=1
                            continue
                        filename=raw_argv[i+1]
                        i+=2
                else:
                    stderr_buf.append("o: empty parameter")
                    i+=1
                    continue
                fmt_map={'L':'list','J':'json','D':'ndjson','G':'grepable','B':'binary','X':'xml','U':'unicornscan'}
                fmt=fmt_map.get(fmt_char.upper())
                if fmt:
                    cfg['output_format']=fmt
                    cfg['output_filename']=filename
                continue
            else:
                if token in ('-Pn','-n','-sS'):
                    i+=1
                    continue
                sys.stderr.write(f"FAIL: unknown command-line parameter \"{token.lstrip('-')}\"\n")
                sys.stderr.write(f" [hint] did you want \"--{token.lstrip('-')}\"?\n")
                sys.exit(1)

        r,err=parse_ip_token(token)
        if r:
            cfg['include_ranges'].append(r)
            i+=1
            continue
        else:
            sys.stderr.write(f"FAIL: unknown command-line parameter \"{token}\"\n")
            sys.stderr.write(f" [hint] did you want \"--{token}\"?\n")
            sys.exit(1)

    if cfg['ping']:
        cfg['ports_ranges'].append(('icmp',0,0))

    winning_mode = last_mode
    if winning_mode is None:
        if has_echo:
            winning_mode='echo'
        elif has_readscan or cfg['readscan'] is not None:
